#include <iostream>
#include <vector>
#include <queue>
#include <cstring>
#include <algorithm>
using namespace std;

const int MAXN = 210;
const int INF = 0x3f3f3f3f;

struct FlowNetwork {
    int cap[MAXN][MAXN], flow[MAXN][MAXN], adj[MAXN][MAXN], deg[MAXN];
    int nodeCount, s, t;
    int height[MAXN], countH[MAXN], visited[MAXN];

    void init(int n) {
        nodeCount = n;
        memset(cap, 0, sizeof(cap));
        memset(adj, 0, sizeof(adj));
        memset(deg, 0, sizeof(deg));
        for (int i = 0; i <= n; i++) {
            height[i] = 0;
            countH[i] = 0;
        }
    }

    void addEdge(int u, int v, int c) {
        cap[u][v] += c;
        if (!adj[u][v]) { adj[u][v] = 1; deg[u]++; }
    }

    int sendFlow(int u, int flowIn) {
        if (u == t) return flowIn;
        int totalFlow = 0;
        for (int v = 0; v < nodeCount; v++) {
            if (cap[u][v] - flow[u][v] > 0 && height[u] == height[v] + 1) {
                int pushed = min(flowIn, cap[u][v] - flow[u][v]);
                int pushedFlow = sendFlow(v, pushed);
                if (pushedFlow > 0) {
                    flow[u][v] += pushedFlow;
                    flow[v][u] -= pushedFlow;
                    totalFlow += pushedFlow;
                    flowIn -= pushedFlow;
                    if (flowIn == 0) break;
                }
            }
        }
        if (totalFlow == 0) {
            int minH = nodeCount;
            for (int v = 0; v < nodeCount; v++) {
                if (cap[u][v] - flow[u][v] > 0) minH = min(minH, height[v]);
            }
            if (--countH[height[u]] == 0) height[s] = nodeCount;
            height[u] = minH + 1;
            countH[height[u]]++;
        }
        return totalFlow;
    }

    int maxFlow(int s_, int t_) {
        s = s_; t = t_;
        memset(flow, 0, sizeof(flow));
        memset(height, 0, sizeof(height));
        memset(countH, 0, sizeof(countH));
        for (int i = 0; i <= nodeCount; i++) height[i] = 0;
        countH[0] = nodeCount;
        int totalFlow = 0;
        while (height[s] < nodeCount) {
            totalFlow += sendFlow(s, INF);
        }
        return totalFlow;
    }
};

struct Point {
    int x, y, dist;
};

int n, T;
int startX, startY;
int dx[4] = {0, 0, -1, 1};
int dy[4] = {-1, 1, 0, 0};
char maze1[210][210], maze2[210][210];
int distMap[210][210], visited[210][210];

int nodeID(int i, int j) {
    return (i - 1) * n + j;
}

bool inRange(int x, int y) {
    return x >= 1 && x <= n && y >= 1 && y <= n;
}

void BFS1() {
    queue<Point> q;
    Point p, np;
    p.x = startX; p.y = startY; p.dist = 0;
    q.push(p);
    memset(distMap, 0x7f, sizeof(distMap));
    memset(visited, 0, sizeof(visited));
    visited[startX][startY] = 1;
    while (!q.empty()) {
        p = q.front(); q.pop();
        distMap[p.x][p.y] = p.dist;
        if (p.dist > T) break;
        for (int k = 0; k < 4; k++) {
            int nx = p.x + dx[k], ny = p.y + dy[k];
            if (inRange(nx, ny) && maze1[nx][ny] != 'Y' && !visited[nx][ny]) {
                np.x = nx; np.y = ny; np.dist = p.dist + 1;
                visited[nx][ny] = 1;
                q.push(np);
            }
        }
    }
}

void BFS2(int i, int j) {
    queue<Point> q;
    Point p, np;
    p.x = i; p.y = j; p.dist = 0;
    memset(visited, 0, sizeof(visited));
    visited[i][j] = 1;
    q.push(p);
    while (!q.empty()) {
        p = q.front(); q.pop();
        if (p.dist > T) break;
        if (distMap[p.x][p.y] < p.dist) continue;
        if ((distMap[p.x][p.y] == p.dist && maze2[p.x][p.y] < '1') || maze2[p.x][p.y] > '9') continue;
        if (maze2[p.x][p.y] >= '1' && maze2[p.x][p.y] <= '9') {
            if (p.x != i || p.y != j)
                maxFlow.addEdge(nodeID(i, j), nodeID(p.x, p.y) + n * n, INF);
            if (distMap[p.x][p.y] == p.dist) continue;
        }
        for (int k = 0; k < 4; k++) {
            int nx = p.x + dx[k], ny = p.y + dy[k];
            if (inRange(nx, ny) && maze1[nx][ny] != 'Y' && !visited[nx][ny]) {
                np.x = nx; np.y = ny; np.dist = p.dist + 1;
                visited[nx][ny] = 1;
                q.push(np);
            }
        }
    }
}

int main() {
    scanf("%d%d", &n, &T);
    for (int i = 1; i <= n; i++) scanf("%s", maze1[i] + 1);
    for (int i = 1; i <= n; i++) scanf("%s", maze2[i] + 1);
    int s = 0, e = 2 * n * n + 1;
    maxFlow.init(e + 1);
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) {
            if (maze1[i][j] >= '1' && maze1[i][j] <= '9') {
                maxFlow.addEdge(s, nodeID(i, j), maze1[i][j] - '0');
            }
            if (maze1[i][j] == 'Z') {
                startX = i; startY = j;
            }
        }
    }
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) {
            maxFlow.addEdge(nodeID(i, j), nodeID(i, j) + n * n, INF);
            if (maze2[i][j] >= '1' && maze2[i][j] <= '9') {
                maxFlow.addEdge(nodeID(i, j) + n * n, e, maze2[i][j] - '0');
            }
        }
    }
    BFS1();
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) {
            if (maze1[i][j] >= '1' && maze1[i][j] <= '9') BFS2(i, j);
        }
    }
    int res = maxFlow.maxFlow(s, e);
    printf("%d\n", res);
}
